CREATE TEMP TABLE fork_selected_checkpoints AS SELECT checkpoint_id FROM checkpoints cp WHERE NOT EXISTS (SELECT 1 FROM context_view_items member WHERE member.view_id=cp.view_id AND NOT EXISTS(SELECT 1 FROM fork_selected_items selected WHERE selected.item_id=member.item_id)) AND NOT EXISTS(SELECT 1 FROM checkpoint_channels channel JOIN context_view_items member ON member.view_id=channel.context_view_id WHERE channel.checkpoint_id=cp.checkpoint_id AND NOT EXISTS(SELECT 1 FROM fork_selected_items selected WHERE selected.item_id=member.item_id)) AND (json_type(cp.metadata_json,'$.boxteam_execution_binding') IS NULL OR json_extract(cp.metadata_json,'$.boxteam_execution_binding.execution_id') IN (SELECT execution_id FROM fork_selected_executions))
